"""Inspect the workspace: list files and report SQLite schema (read-only)."""
import os
import sqlite3
import sys

HERE = os.path.dirname(os.path.abspath(__file__))


def main() -> int:
    print(f"Workspace: {HERE}")
    print("\nFiles:")
    for name in sorted(os.listdir(HERE)):
        full = os.path.join(HERE, name)
        kind = "dir" if os.path.isdir(full) else "file"
        print(f"  [{kind}] {name}")

    dbs = [
        name
        for name in os.listdir(HERE)
        if name.endswith((".db", ".sqlite", ".sqlite3"))
        and os.path.isfile(os.path.join(HERE, name))
    ]
    if not dbs:
        print("\nNo SQLite database files found.")
        return 0

    for name in dbs:
        path = os.path.join(HERE, name)
        print(f"\nDatabase: {name}")
        try:
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as conn:
                tables = conn.execute(
                    "SELECT name FROM sqlite_master"
                    " WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("  (no tables)")
                for (table,) in tables:
                    cols = conn.execute(f'PRAGMA table_info("{table}")').fetchall()
                    print(f"  table: {table}")
                    for cid, cname, ctype, notnull, dflt, pk in cols:
                        print(
                            f"    {cname} {ctype} notnull={notnull} pk={pk} default={dflt}"
                        )
        except sqlite3.Error as exc:
            print(f"  error reading schema: {exc}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

